Ray march:
```glsl
float rayMarch(vec3 ro, vec3 rd, out float t, out float mid){
  float t=0.0, m=-1.0;
  for(int i=0;i<MAXSTEPS;i++){
    vec3 pos=ro+rd*t;
    vec2 h=map(pos);
    if(abs(h.x)<EPSILON*t){ m=h.y; break; }
    t+=h.x;
    if(t>tmax){ m=-1.0; break; }
    mid=t;
  }
  return m;
}
```

Soft shadow:
```glsl
float softShadow(vec3 ro, vec3 ld, float tmin, float tmax){
  float res=1.0, t=tmin;
  for(int i=0;i<32;i++){
    float h=map(ro+ld*t).x;
    res=min(res, k*h/t);
    t+=clamp(h,0.01,0.2);
    if(res<0.005 || t>tmax) break;
  }
  return clamp(res,0.0,1.0);
}
```

AO:
```glsl
float calcAO(vec3 p, vec3 n){
  float occ=0.0, sca=1.0;
  for(int i=0;i<5;i++){
    float h=0.02+0.11*float(i);
    occ+=(h-map(p+n*h).x)*sca;
    sca*=0.8;
  }
  return clamp(1.0-2.5*occ,0.0,1.0);
}
```

Normal:
```glsl
vec3 calcNormal(vec3 p){
  const float h=0.001;
  const vec2 k=vec2(1.0,-1.0);
