Standard iq formula:
```glsl
float mandelbulb( in vec3 p, in float power ) {
  vec3 z = p;
  float dr = 1.0;
  float r = 0.0;
  for( int i=0; i<8; i++ ) {
    r = length(z);
    if( r>2.0 ) break;
    float theta = acos( z.z/r );
    float phi = atan( z.y, z.x );
    dr  = pow(r,power-1.0)*power*dr + 1.0;
    float zr = pow( r, power );
    theta *= power;
    phi   *= power;
    z = zr*vec3( sin(theta)*cos(phi), sin(phi)*sin(theta), cos(theta) ) + p;
  }
  return 0.5*log(r)/dr;
}
```
