The page should also include an "Algorithm" code block (pseudocode):

```glsl
// ray march: advance the ray by the distance to the surface
float raymarch(vec3 ro, vec3 rd, out float t, out float mat){
    float d = 0.0;
    mat = -1.0;
    for( int i = 0; i < MAX_STEPS; i++ ) {
        vec3  p = ro + rd * d;          // sample point on the ray
        float s = sdf(p);               // distance to nearest surface
        if( s < 0.001 * d ) {           // close enough? → hit
            mat = material(p);
            break;
        }
        d += s;                         // safe to skip: s is a lower bound
        if( d > MAX_DIST ) break;       // escaped the scene
    }
    t = d;
}
```

