Now the JS engine — let's write it robustly:

```js
(function(){
  'use strict';
  const RM = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;
  const DPR_CAP = Math.min(window.devicePixelRatio || 1, 2);

  const VERT = 'attribute vec2 aPos; void main(){ gl_Position = vec4(aPos, 0.0, 1.0); }';

  function sh(gl, type, src){
    const s = gl.createShader(type);
    gl.shaderSource(s, src); gl.compileShader(s);
    if(!gl.getShaderParameter(s, gl.COMPILE_STATUS)){
      console.error(gl.getShaderInfoLog(s), src); return null;
    }
    return s;
  }

  function makeEngine(canvas, fragSrc){
    const gl = canvas.getContext('webgl', {antialias:false, alpha:false, depth:false, stencil:false, powerPreference:'high-performance'})
            || canvas.getContext('experimental-webgl');
    if(!gl) return null;
    const vs = sh(gl, gl.VERTEX_SHADER, VERT);
    const fs = sh(gl, gl.FRAGMENT_SHADER, fragSrc);
    if(!vs || !fs) return null;
    const prog = gl.createProgram();
    gl.attachShader(prog, vs); gl.attachShader(prog, fs); gl.linkProgram(prog);
    if(!gl.getProgramParameter(prog, gl.LINK_STATUS)){ console.error(gl.getProgramInfoLog(prog)); return null; }
    gl.useProgram(prog);
    const buf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1, 3,-1, -1,3]), gl.STATIC_DRAW);
    const loc = gl.getAttribLocation(prog, 'aPos');
    gl.enableVertexAttribArray(loc);
    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
    const uni = {};
    const re = /uniform\s+[\w]+\s+([a-zA-Z_]\w*)/g; let m;
    while((m = re.exec(fragSrc))) uni[m[1]] = gl.getUniformLocation(prog, m[1]);
    return { gl, uni, draw(){ gl.drawArrays(gl.TRIANGLES, 0, 3); },
      set(vals){ for(const k in vals){ const u=uni[k]; if(!u) continue; const v=vals[k];
        if(typeof v === 'number') gl.uniform1f(u, v);
        else if(Array.isArray(v)){ if(v.length===2) gl.uniform2f(u,v[0],v[1]); else if(v.length===3) gl.uniform3f(u,v[0],v[1],v[2]); else gl.uniform4f(u,v[0],v[1],v[2],v[3]); }
      } } };
  }
```

