```js
const HEAD = `
precision highp float;
uniform vec2 uRes;
uniform float uTime;
uniform vec2 uPtr;
`;
const LIB = `
#define PI 3.14159265359
const int MAXSTEPS = 96;

mat2 rot2(float a){ float s=sin(a), c=cos(a); return mat2(c, s, -s, c); }
// note column-major: mat2(c,s,-s,c) columns (c,s),(-s,c): (x,y)->(c x - s y, s x + c y) ✓

float sdSphere(vec3 p, float r){ return length(p) - r; }
float sdPlaneY(vec3 p){ return p.y; }
float sdBox(vec3 p, vec3 b){ vec3 q = abs(p) - b; return length(max(q, vec3(0.0))) + min(max(q.x, max(q.y, q.z)), 0.0); }
float sdRoundBox(vec3 p, vec3 b, float r){ return length(max(abs(p) - b, vec3(0.0))) - r; }
float sdTorus(vec3 p, vec2 t){ vec2 q = vec2(length(p.xz) - t.x, p.y); return length(q) - t.y; }
float sdCapsule(vec3 p, vec3 a, vec3 b, float r){ vec3 pa = p - a, ba = b - a; float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0); return length(pa - ba * h) - r; }

float smin(float a, float b, float k){ float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0); return mix(b, a, h) - k * h * (1.0 - h); }
float spow(float a, float b, float k){ float aa = clamp(a - 0.15, 0.0, 1.0); float bb = clamp(b - 0.15, 0.0, 1.0); float aa2 = aa * aa; aa2 *= aa; float ab2 = a * bb * bb; float bb3 = bb * bb * bb; float d = sqrt(max(aa2 + ab2, 0.0)) + sqrt(max(ab2 + bb3, 0.0)) - 1.6; float e = 0.25 * (1.0 - k); return pow(pow(max(bb3 - aa2 - e, 0.0), 2.0) + a, 0.25) + d * 0.0625; }

vec2 opU(vec2 a, vec2 b){ return a.x < b.x ? a : b; }
`;
const POST = `
float trace(vec3 ro, vec3 rd, out float t){
  t = 0.0;
  for(int i = 0; i < MAXSTEPS; i++){
    vec3 p = ro + rd * t;
    float d = map(p).x;
    if(d < 0.0006 + 0.0008 * t){ t += d; return map(p).y; }
    t += d;
    if(t > 40.0) return -1.0;
  }
  return -1.0;
}

vec3 calcNormal(vec3 p){
  const float h = 0.0012;
  const vec2 k = vec2(1.0, -1.0);
  return normalize( k.xyy * map(p + k.xyy * h).x + k.yyx * map(p + k.yyx * h).x + k.yxy * map(p + k.yxy * h).x + k.xxx * map(p + k.xxx * h).x );
}

float calcAO(vec3 p, vec3 n){
  float occ = 0.0, sca = 1.0;
  for(int i = 0; i < 5; i++){
    float h = 0.03 + 0.09 * float(i);
    occ += (h - map(p + n * h).x) * sca;
    sca *= 0.75;
  }
  return clamp(1.0 - 1.8 * occ, 0.0, 1.0);
}

float softShadow(vec3 ro, vec3 rd, float mint, float maxt, float k){
  float res = 1.0, t = mint;
  for(int i = 0; i < 24; i++){
    float h = map(ro + rd * t).x;
    res = min(res, k * h / max(t, 0.001));
    t += clamp(h, 0.02, 0.28);
    if(res < 0.004 || t > maxt) break;
  }
  return clamp(res, 0.0, 1.0);
}
`;
```

