void main(){
  vec2 uv = (gl_FragCoord.xy - 0.5 * uRes) / uRes.y;
  float a = uTime * 0.12 + uPtr.x * 0.5;
  vec3 ro = vec3(sin(a) * 3.6, 1.5 + uPtr.y * 0.4, cos(a) * 3.6);
  vec3 ta = vec3(0.0, 0.55, 0.0);
  vec3 rd = camRay(uv, ro, ta, 1.9);
  float t; float mid = trace(ro, rd, t);
  vec3 col;
  if(mid < 0.0){
    col = heroSky(rd);
  } else {
    vec3 p = ro + rd * t;
    vec3 n = calcNormal(p);
    vec3 lig = normalize(vec3(0.65, 0.85, -0.45));
    float dif = clamp(dot(n, lig), 0.0, 1.0);
    float sho = softShadow(p + n * 0.012, lig, 0.04, 18.0, 2.0);
    float ao = calcAO(p, n);
    if(mid < 1.5){
      float fre = pow(clamp(1.0 + dot(n, rd), 0.0, 1.0), 3.0);
      vec3 base = vec3(0.10, 0.34, 0.33);
      col = base * (0.10 + 1.05 * dif * sho) * ao;
      col += vec3(1.0, 0.62, 0.30) * fre * 0.4 * (0.3 + 0.7 * sho);
      col += vec3(0.2, 0.8, 0.7) * pow(clamp(dot(n, normalize(lig + rd)),0.0,1.0), 40.0) * 0.25 * sho; // spec
    } else {
      vec2 g = abs(fract(p.xz * 0.6) - 0.5);
      float line = smoothstep(0.47, 0.44, min(g.x, g.y));
      vec3 base = vec3(0.045, 0.065, 0.09) + vec3(0.05, 0.18, 0.16) * line;
      col = base * (0.18 + 0.85 * dif * sho) * ao;
    }
    col = mix(col, heroSky(rd), 1.0 - exp(-0.0020 * t * t));
  }
  col *= 1.0 - 0.35 * dot(uv * 0.9, uv * 0.9); // vignette
  gl_FragColor = vec4(pow(col / (1.0 + col), vec3(0.4545)), 1.0);
}
vec3 heroSky(vec3 rd){
  float t = clamp(rd.y * 0.5 + 0.5, 0.0, 1.0);
  vec3 c = mix(vec3(0.030, 0.045, 0.070), vec3(0.085, 0.140, 0.200), t);
  vec3 l = normalize(vec3(0.65, 0.85, -0.45));
  c += vec3(1.0, 0.60, 0.30) * pow(clamp(dot(rd, l), 0.0, 1.0), 32.0) * 0.35;
  return c;
}
