```glsl
vec3 camRay(vec2 uv, vec3 ro, vec3 ta, float fl){
  vec3 fw = normalize(ta - ro);
  vec3 rt = normalize(cross(fw, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(rt, fw);
  return normalize(fw * fl + uv.x * rt + uv.y * up);
}
