```
// Ray marching a.k.a. sphere tracing — the core loop
float scene(vec3 p);          // returns signed distance to the surface

float raymarch(vec3 ro, vec3 rd, out float t){
    t = 0.0;
    for (int i = 0; i < 96; i++){
        vec3  p = ro + rd * t;        // 1) sample the ray at arc length t
        float s = scene(p);           // 2) signed distance to the nearest surface

        if (s < 0.0006 + 0.0008 * t)  // 3) inside the epsilon shell? -> hit
            break;
        t += s;                       // 4) advance — guaranteed not to cross
        if (t > 40.0) return -1.0;    // 5) left the scene -> sky
    }
    return t;
}
```
