```js
function createRenderer(canvas, frag){
  const gl = canvas.getContext('webgl',{antialias:false}) || canvas.getContext('experimental-webgl',{antialias:false});
  if(!gl) return null;
  function sh(type,src){ const s=gl.createShader(type); gl.shaderSource(s,src); gl.compileShader(s); if(!gl.getShaderParameter(s,gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s)); return s; }
  const v=sh(gl.VERTEX_SHADER, 'attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}');
  const f=sh(gl.FRAGMENT_SHADER, frag);
  const prog=gl.createProgram(); gl.attachShader(prog,v); gl.attachShader(prog,f); gl.linkProgram(prog);
  if(!gl.getProgramParameter(prog,gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(prog));
  gl.useProgram(prog);
  const buf=gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER,buf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1, 3,-1, -1,3]), gl.STATIC_DRAW);
  const loc=gl.getAttribLocation(prog,'p');
  gl.enableVertexAttribArray(loc);
  gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);
  const u={};
  const names=['uRes','uTime','uMouse','uSpeed','uMode','uQuality','uSeed'];
  names.forEach(n=>u[n]=gl.getUniformLocation(prog,n));
  return {gl, u,
    draw(){ gl.uniform2f(u.uRes, canvas.width, canvas.height); gl.drawArrays(gl.TRIANGLES,0,3); } };
}
