  float fl = p.y + 0.55 + 0.10*noise(p.xz*1.6 + t*0.15);
  return min(m, fl);
}
vec3 calcNormal(vec3 p, float t){ const vec2 e=vec2(0.002,0.0); return normalize(vec3(map(p+e.xyy,t)-map(p-e.xyy,t), map(p+e.yxy,t)-map(p-e.yxy,t), map(p+e.yyx,t)-map(p-e.yyx,t))); }

void main(){
  vec2 uv = (gl_FragCoord.xy - 0.5*uRes)/uRes.y;
  float t = uTime * uSpeed;
  vec2 m = vec2(uMouse.x, uMouse.y);
  float pulse = 1.0 + 0.12*smoothstep(0.0,1.0,uMouse.z);
  vec3 ro = vec3(m.x*1.7, 0.4 + m.y*1.2, 3.4);
  vec3 ta = vec3(m.x*0.6, 0.3 + m.y*0.4, 0.0);
  vec3 fw = normalize(ta - ro);
  vec3 rt = normalize(cross(fw, vec3(0.0,1.0,0.0)));
  vec3 up = cross(rt, fw);
  vec3 rd = normalize(uv.x*rt + uv.y*up + 1.65*fw);

  float d = 0.0;
  for (int i = 0; i < 128; i++) {
    vec3 p = ro + rd*d;
    float h = map(p, t);
    if (h < 0.0008) break;
    d += h;
    if (d > 30.0) break;
  }
  vec3 col = vec3(0.0);
  vec3 p = ro + rd*d;
  if (d < 30.0) {
    vec3 n = calcNormal(p, t);
    vec3 lig = normalize(vec3(0.65, 0.9, -0.35));
    float dif = clamp(dot(n, lig), 0.0, 1.0);
    float amb = clamp(0.5 + 0.5*n.y, 0.0, 1.0);
    float fre = pow(clamp(1.0 + dot(n, rd), 0.0, 1.0), 3.0);
    float spec = pow(clamp(dot(reflect(rd, n), lig), 0.0, 1.0), 40.0) * dif;
    vec3 alb = p.y > -0.2 ? mix(vec3(1.0, 0.52, 0.28), vec3(0.25, 0.85, 0.85), smoothstep(-0.4, 1.3, p.x)) : vec3(0.14, 0.28, 0.34);
    col = alb * (0.65*dif + 0.3*amb) + vec3(1.0,0.95,0.9)*spec + vec3(0.5,0.7,0.9)*fre*0.15;
  } else {
    vec3 sky = mix(vec3(0.015,0.04,0.08), vec3(0.05,0.12,0.19), 0.5+0.5*uv.y);
    col = sky;
  }
  float fog = 1.0 - exp(-d*d*0.0012);
  col = mix(col, vec3(0.03,0.07,0.11), fog);
  col = col / (1.0 + col*0.8);
  col = pow(col, vec3(0.4545));
  // grain + vignette
  float g = hash21(gl_FragCoord.xy + uTime);
  col += (g - 0.5) * 0.03;
  float vig = smoothstep(1.5, 0.4, length(uv));
  col *= 0.75 + 0.25*vig;
  gl_FragColor = vec4(col, 1.0);
}
