```
precision highp float;
uniform vec2 uRes; uniform float uTime; uniform vec3 uMouse; uniform float uSpeed; uniform float uQuality; uniform float uSeed;
COMMON

float map(vec3 p){
  float t = uTime * uSpeed;
  float s = uSeed;
  float m;
  if (uMode < 0.5) {
    // shapes: sphere + box, plain union
    m = sdSphere(p - vec3(-0.9, 0.85 + 0.15*sin(t*1.2), 0.0), 0.42 + 0.05*sin(t*1.7));
    m = min(m, sdBox(p - vec3(0.75, 0.7 + 0.12*sin(t*0.9+2.0), 0.0), vec3(0.35) + 0.04*sin(t)));
  } else if (uMode < 1.5) {
    // metaballs: smooth union of orbiting spheres
    m = 1e5;
    vec3 c1 = vec3(cos(t)*1.1, 0.9+0.1*sin(t*2.1), sin(t)*0.3);
    vec3 c2 = vec3(cos(t+2.1)*1.0, 1.05, sin(t+2.1)*0.5);
    vec3 c3 = vec3(cos(t+4.2)*0.9, 0.75, sin(t+4.2)*0.4);
    m = smin(m, sdSphere(p - c1, 0.34), 0.35);
    m = smin(m, sdSphere(p - c2, 0.30), 0.35);
    m = smin(m, sdSphere(p - c3, 0.26), 0.35);
    m = smin(m, sdSphere(p - vec3(0.0, 1.15, 0.0), 0.30), 0.35);
  } else if (uMode < 2.5) {
    // torus + sphere, hard union
    m = sdTorus(p - vec3(0.0, 0.95, 0.0) - 0.0, vec2(0.75, 0.26));
    m = min(m, sdSphere(p - vec3(0.0, 0.95 + 0.9*sin(t), 0.0), 0.18));
  } else {
    // smooth blend: box + 2 spheres
    m = sdBox(p - vec3(0.0, 0.6, 0.0), vec3(0.45));
    m = smin(m, sdSphere(p - vec3(0.85, 0.75, 0.0), 0.34), 0.3);
    m = smin(m, sdSphere(p - vec3(-0.85, 0.75, 0.0), 0.34), 0.3);
  }
  // wavy floor
  float fl = p.y + 0.62 + 0.10*noise(p.xz*1.4 + t*0.1) + 0.05*noise(p.xz*4.0 - t*0.2);
  return min(m, fl);
}
```

