vec3 calcNormal(vec3 p){ const vec2 e=vec2(0.0015,0.0); return normalize(vec3(map(p+e.xyy)-map(p-e.xyy), map(p+e.yxy)-map(p-e.yxy), map(p+e.yyx)-map(p-e.yyx))); }
float softShadow(vec3 ro, vec3 rd){
  float res = 1.0; float t = 0.03;
  for (int i = 0; i < 28; i++) {
    float h = map(ro + rd*t);
    res = min(res, 9.0*h/t);
    t += clamp(h, 0.02, 0.4);
    if (res < 0.005 || t > 10.0) break;
  }
  return clamp(res, 0.0, 1.0);
}
void main(){
  vec2 uv = (gl_FragCoord.xy - 0.5*uRes)/uRes.y;
  float t = uTime * uSpeed;
  float steps = uQuality < 0.5 ? 48.0 : (uQuality < 1.5 ? 96.0 : 160.0);
