  vec3 ta = vec3(0.0, 0.85, 0.0);
  vec3 fw = normalize(ta - ro);
  vec3 rt = normalize(cross(fw, vec3(0.0,1.0,0.0)));
  vec3 up = cross(rt, fw);
  vec3 rd = normalize(uv.x*rt + uv.y*up + 1.7*fw);
  float d = 0.0; bool hit = false;
  for (int i = 0; i < 160; i++) {
    if (float(i) > steps) break;
    float h = map(ro + rd*d);
    if (h < 0.0008) { hit = true; break; }
    d += h;
    if (d > 24.0) break;
  }
  vec3 col;
  vec3 pal = uMode < 0.5 ? vec3(1.0,0.5,0.3)
            : uMode < 1.5 ? vec3(1.0,0.78,0.35)
            : uMode < 2.5 ? vec3(0.3,0.85,0.85)
            : vec3(0.62,0.45,1.0);
  if (hit) {
    vec3 p = ro + rd*d;
    vec3 n = calcNormal(p);
    vec3 lig = normalize(vec3(0.6 + 0.3*uMouse.x, 0.9, -0.4 + 0.3*uMouse.y));
    float sha = softShadow(p + n*0.02, lig);
    float dif = clamp(dot(n, lig), 0.0, 1.0) * sha;
    float amb = 0.5 + 0.5*n.y;
    float fre = pow(clamp(1.0 + dot(n, rd), 0.0, 1.0), 4.0);
    float spec = pow(clamp(dot(reflect(rd, n), lig), 0.0, 1.0), 48.0) * sha;
    vec3 alb = p.y < 0.0 ? vec3(0.10, 0.16, 0.20) : pal;
    col = alb*(0.7*dif + 0.22*amb) + vec3(1.0,0.96,0.9)*spec*0.9 + vec3(0.55,0.7,0.95)*fre*0.22;
  } else {
    col = mix(vec3(0.012,0.03,0.06), vec3(0.05,0.10,0.16), 0.5 + 0.5*uv.y);
