Sample A (camera + walk) — file name "core_walk.glsl":
```
<span class="c">// One ray per pixel: build a camera, then walk it to the surface</span>
<span class="t">vec3</span> ro = <span class="f">vec3</span>(<span class="n">0.0</span>, <span class="n">0.6</span>, <span class="n">3.0</span>);  <span class="c">// camera position</span>
<span class="t">vec3</span> ta = <span class="f">vec3</span>(<span class="n">0.0</span>, <span class="n">0.3</span>, <span class="n">0.0</span>);  <span class="c">// where we're aiming</span>
<span class="t">vec3</span> fw = <span class="f">normalize</span>(ta - ro);
<span class="t">vec3</span> rt = <span class="f">normalize</span>(<span class="f">cross</span>(fw, <span class="f">vec3</span>(<span class="n">0.0</span>,<span class="n">1.0</span>,<span class="n">0.0</span>)));
<span class="t">vec3</span> up = <span class="f">cross</span>(rt, fw);
<span class="t">vec3</span> rd = <span class="f">normalize</span>(uv.x * rt + uv.y * up + <span class="n">1.7</span> * fw);

<span class="t">float</span> t = <span class="n">0.0</span>;
<span class="k">for</span> (<span class="t">int</span> i = <span class="n">0</span>; i < <span class="n">128</span>; i++) {
    <span class="t">vec3</span>  p = ro + rd * t;   <span class="c">// probe point along the ray</span>
    <span class="t">float</span> d = <span class="f">sceneSDF</span>(p); <span class="c">// signed distance to the surface</span>

    <span class="k">if</span> (d < <span class="n">0.001</span>) <span class="k">break</span>;  <span class="c">// hit — p is on the surface</span>
    t += d;               <span class="c">// exact step: can never skip the surface</span>
}
