<span class="c">// A signed distance field (SDF): the whole "mesh" is this function.</span>
<span class="c">// f(p) &gt; 0  → outside      f(p) &lt; 0  → inside      f(p) = 0  → surface</span>

<span class="t">float</span> <span class="f">sdSphere</span>(<span class="t">vec3</span> p, <span class="t">float</span> r)  { <span class="k">return</span> <span class="f">length</span>(p) - r; }
<span class="t">float</span> <span class="f">sdBox</span>(<span class="t">vec3</span> p, <span class="t">vec3</span> b)    { <span class="k">return</span> <span class="f">length</span>(<span class="f">max</span>(<span class="f">abs</span>(p)-b, <span class="n">0.0</span>)) + <span class="f">min</span>(<span class="f">max</span>(...), <span class="n">0.0</span>); }
