<span class="c">// March a second ray toward the light; never sample the SDF directly</span>
<span class="t">float</span> <span class="f">softShadow</span>(<span class="t">vec3</span> ro, <span class="t">vec3</span> rd) {
    <span class="t">float</span> res = <span class="n">1.0</span>;
    <span class="t">float</span> t   = <span class="n">0.02</span>;
    <span class="k">for</span> (<span class="t">int</span> i = <span class="n">0</span>; i < <span class="n">32</span>; i++) {
