/* ============================================================
   DIAGRAM
============================================================ */
.fig{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:18px;position:relative;overflow:hidden}
.fig::before{content:"";position:absolute;inset:0;background:radial-gradient(420px 260px at 72% 40%,var(--accent-soft),transparent 70%);pointer-events:none}
.fig svg{width:100%;height:auto;position:relative}
.d-lbl{font:11.5px var(--mono);fill:var(--muted);letter-spacing:.03em}
.d-lbl.hot{fill:var(--accent)}
.d-blob{stroke-width:1.6}
.d-cam{fill:var(--panel2);stroke:var(--line2);stroke-width:1.5}
.d-lens{fill:var(--accent);opacity:.9}
.d-ray{stroke:var(--accent2);stroke-width:2;fill:none;stroke-dasharray:7 6;animation:dash 1.5s linear infinite}
@keyframes dash{to{stroke-dashoffset:-26}}
.d-ink{fill:var(--accent2)}
.d-dot{fill:var(--text);opacity:.65}
.d-hitcore{fill:var(--accent)}
.d-hitring{fill:none;stroke:var(--accent);stroke-width:1.5;transform-box:fill-box;transform-origin:center;animation:ring 2.4s ease-out infinite}
@keyframes ring{0%{transform:scale(.45);opacity:.9}100%{transform:scale(2.6);opacity:0}}
.fig-cap{display:flex;justify-content:space-between;gap:12px;padding:12px 6px 2px;font-family:var(--mono);font-size:.68rem;letter-spacing:.06em;color:var(--faint)}

/* ============================================================
   PLAYGROUND
============================================================ */
.pg{display:grid;grid-template-columns:300px 1fr;gap:20px;align-items:start}
@media (max-width:980px){.pg{grid-template-columns:1fr}}
.ctl{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:20px;display:grid;gap:20px}
.ctl-label{font-family:var(--mono);font-size:.64rem;letter-spacing:.2em;text-transform:uppercase;color:var(--faint);margin-bottom:10px;display:flex;justify-content:space-between;align-items:baseline}
.ctl-label .val{color:var(--accent);letter-spacing:.05em;font-size:.7rem}
.seg{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}
.seg.three{grid-template-columns:repeat(3,1fr)}
.seg button{
  font:600 12.3px var(--mono);letter-spacing:.02em;padding:10px 6px;border-radius:10px;
  border:1px solid var(--line2);background:var(--panel2);color:var(--muted);cursor:pointer;
  transition:all .18s ease;
}
.seg button:hover{color:var(--text);border-color:var(--accent)}
.seg button.on{color:var(--text);border-color:var(--accent);background:var(--accent-soft);box-shadow:inset 0 0 0 1px var(--accent)}
input[type=range]{width:100%;appearance:none;-webkit-appearance:none;height:4px;border-radius:2px;background:var(--line2);outline:none;margin:6px 0 2px}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:17px;height:17px;border-radius:50%;background:var(--accent);border:3px solid var(--bg);box-shadow:0 0 0 1px var(--line2);cursor:pointer;transition:transform .15s}
input[type=range]::-webkit-slider-thumb:hover{transform:scale(1.15)}
