  rvEls.forEach(function(el){ io.observe(el); });
} else {
  rvEls.forEach(function(el){ el.classList.add('in'); });
}

/* ================= COPY BUTTONS ================= */
Array.prototype.slice.call(document.querySelectorAll('.copy-btn')).forEach(function(btn){
  btn.addEventListener('click', function(){
    var pre = btn.closest('.code').querySelector('pre');
    function done(){ btn.textContent = 'Copied ✓'; setTimeout(function(){ btn.textContent = 'Copy'; }, 1400); }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(pre.innerText).then(done, function(){ fallback(); done(); });
    } else { fallback(); done(); }
    function fallback(){
      var r = document.createRange(); r.selectNodeContents(pre);
      var sel = window.getSelection(); sel.removeAllRanges(); sel.addRange(r);
      try { document.execCommand('copy'); } catch(e){}
      sel.removeAllRanges();
    }
  });
});

/* ================= SHADERS ================= */
var PRE = 'precision highp float;\n';
var COMMON =
'float hash21(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }\n' +
'float noise(vec2 p){\n' +
'  vec2 i = floor(p); vec2 f = fract(p);\n' +
'  f = f*f*(3.0 - 2.0*f);\n' +
'  float a = hash21(i);\n' +
'  float b = hash21(i + vec2(1.0,0.0));\n' +
'  float c = hash21(i + vec2(0.0,1.0));\n' +
'  float d = hash21(i + vec2(1.0,1.0));\n' +
'  return mix(mix(a,b,f.x), mix(c,d,f.x), f.y);\n' +
'}\n' +
'float sdBox(vec3 p, vec3 b){ vec3 q = abs(p) - b; return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0); }\n' +
'float sdSphere(vec3 p, float r){ return length(p) - r; }\n' +
'float sdTorus(vec3 p, vec2 t){ vec2 q = vec2(length(p.xz) - t.x, p.y); return length(q) - t.y; }\n' +
'float sdOcta(vec3 p, float s){ p = abs(p); return (p.x + p.y + p.z - s) * 0.57735027; }\n' +
'float smin(float a, float b, float k){ float h = clamp(0.5 + 0.5*(b - a)/k, 0.0, 1.0); return mix(b, a, h) - k*h*(1.0-h); }\n';

/* ---- Hero scene: sphere + cube + octahedron over a noisy floor ---- */
var HERO_FRAG = PRE +
'uniform vec2 uRes;\nuniform float uTime;\nuniform vec3 uMouse;\nuniform float uSpeed;\nuniform float uQuality;\n' + COMMON +
'float map(vec3 p, float t){\n' +
'  float m = sdSphere(p - vec3(0.0, 0.15*sin(t*1.4), 0.0), 0.62 + 0.06*sin(t*2.0));\n' +
'  m = min(m, sdBox(p - vec3(1.15, 0.75 + 0.18*sin(t*1.1), 0.35), vec3(0.30) + 0.05*sin(t*0.9)));\n' +
'  if (uQuality > 0.5){\n' +
'    m = min(m, sdOcta(p - vec3(-1.15, 0.7 + 0.15*sin(t*0.8 + 2.0), 0.2) + 0.1*vec3(sin(t), cos(t*0.7), 0.0)));\n' +
'  }\n' +
'  m = min(m, p.y + 0.55 + 0.10*noise(p.xz*1.6 + t*0.15));\n' +
'  return m;\n' +
'}\n' +
'vec3 calcNormal(vec3 p, float t){\n' +
'  const vec2 e = vec2(0.002, 0.0);\n' +
'  return normalize(vec3(\n' +
'    map(p + e.xyy, t) - map(p - e.xyy, t),\n' +
'    map(p + e.yxy, t) - map(p - e.yxy, t),\n' +
'    map(p + e.yyx, t) - map(p - e.yyx, t)));\n' +
'}\n' +
'void main(){\n' +
'  vec2 uv = (gl_FragCoord.xy - 0.5*uRes) / uRes.y;\n' +
'  float t = uTime * uSpeed;\n' +
'  vec2 m = vec2(uMouse.x, uMouse.y);\n' +
'  vec3 ro = vec3(m.x * 1.7, 0.4 + m.y * 1.2, 3.4);\n' +
'  vec3 ta = vec3(m.x * 0.6, 0.3 + m.y * 0.4, 0.0);\n' +
'  vec3 fw = normalize(ta - ro);\n' +
'  vec3 rt = normalize(cross(fw, vec3(0.0, 1.0, 0.0)));\n' +
'  vec3 up = cross(rt, fw);\n' +
'  vec3 rd = normalize(uv.x * rt + uv.y * up + 1.65 * fw);\n' +
'  float d = 0.0;\n' +
'  for (int i = 0; i < 128; i++){\n' +
'    float h = map(ro + rd * d, t);\n' +
'    if (h < 0.0008) break;\n' +
'    d += h;\n' +
'    if (d > 30.0) break;\n' +
'  }\n' +
'  vec3 col;\n' +
'  if (d < 30.0){\n' +
'    vec3 p = ro + rd * d;\n' +
'    vec3 n = calcNormal(p, t);\n' +
'    vec3 lig = normalize(vec3(0.65, 0.9, -0.35));\n' +
'    float dif = clamp(dot(n, lig), 0.0, 1.0);\n' +
'    float amb = clamp(0.5 + 0.5*n.y, 0.0, 1.0);\n' +
'    float fre = pow(clamp(1.0 + dot(n, rd), 0.0, 1.0), 3.0);\n' +
'    float spec = pow(clamp(dot(reflect(rd, n), lig), 0.0, 1.0), 40.0) * dif;\n' +
'    vec3 alb = (p.y > -0.2) ? mix(vec3(1.0, 0.52, 0.28), vec3(0.25, 0.85, 0.85), smoothstep(-0.4, 1.3, p.x)) : vec3(0.14, 0.28, 0.34);\n' +
'    col = alb * (0.65*dif + 0.3*amb) + vec3(1.0, 0.95, 0.9) * spec + vec3(0.5, 0.7, 0.9) * fre * 0.15;\n' +
'  } else {\n' +
'    col = mix(vec3(0.015, 0.04, 0.08), vec3(0.05, 0.12, 0.19), 0.5 + 0.5*uv.y);\n' +
'  }\n' +
'  float fog = 1.0 - exp(-d * d * 0.0012);\n' +
'  col = mix(col, vec3(0.03, 0.07, 0.11), fog);\n' +
'  col = col / (1.0 + col * 0.8);\n' +
'  col = pow(col, vec3(0.4545));\n' +
'  col += (hash21(gl_FragCoord.xy + uTime) - 0.5) * 0.03;\n' +
'  float vig = smoothstep(1.5, 0.4, length(uv));\n' +
'  col *= 0.78 + 0.22 * vig;\n' +
'  gl_FragColor = vec4(col, 1.0);\n' +
'}\n';

/* ---- Playground: 4 SDF modes + soft shadows ---- */
var PG_FRAG = PRE +
'uniform vec2 uRes;\nuniform float uTime;\nuniform vec3 uMouse;\nuniform float uSpeed;\nuniform float uQuality;\nuniform float uMode;\nuniform float uSeed;\n' + COMMON +
'float map(vec3 p){\n' +
'  float t = uTime * uSpeed;\n' +
'  float m;\n' +
'  if (uMode < 0.5){\n' +
'    m = sdSphere(p - vec3(-0.9, 0.85 + 0.15*sin(t*1.2), 0.0), 0.42 + 0.05*sin(t*1.7));\n' +
'    m = min(m, sdBox(p - vec3(0.75, 0.7 + 0.12*sin(t*0.9 + 2.0), 0.0), vec3(0.35) + 0.04*sin(t)));\n' +
'  } else if (uMode < 1.5){\n' +
'    m = 1e5;\n' +
'    m = smin(m, sdSphere(p - vec3(cos(t + uSeed)*1.1, 0.9 + 0.1*sin(t*2.1), sin(t + uSeed)*0.3), 0.34), 0.35);\n' +
'    m = smin(m, sdSphere(p - vec3(cos(t + 2.1)*1.0, 1.05, sin(t + 2.1)*0.5), 0.30), 0.35);\n' +
'    m = smin(m, sdSphere(p - vec3(cos(t + 4.2)*0.9, 0.75, sin(t + 4.2)*0.4), 0.26), 0.35);\n' +
'    m = smin(m, sdSphere(p - vec3(0.0, 1.15, 0.0), 0.30), 0.35);\n' +
'  } else if (uMode < 2.5){\n' +
'    m = sdTorus(p - vec3(0.0, 0.95, 0.0), vec2(0.75, 0.26));\n' +
'    m = min(m, sdSphere(p - vec3(0.0, 0.95 + 0.85*sin(t), 0.0), 0.18));\n' +
'  } else {\n' +
'    m = sdBox(p - vec3(0.0, 0.6, 0.0), vec3(0.45));\n' +
'    m = smin(m, sdSphere(p - vec3(0.85, 0.75, 0.0), 0.34), 0.30);\n' +
'    m = smin(m, sdSphere(p - vec3(-0.85, 0.75, 0.0), 0.34), 0.30);\n' +
'  }\n' +
'  float fl = p.y + 0.62 + 0.10*noise(p.xz*1.4 + t*0.1 + vec2(uSeed*17.0)) + 0.05*noise(p.xz*4.0 - t*0.2);\n' +
'  return min(m, fl);\n' +
'}\n' +
'vec3 calcNormal(vec3 p){\n' +
'  const vec2 e = vec2(0.0015, 0.0);\n' +
'  return normalize(vec3(\n' +
'    map(p + e.xyy) - map(p - e.xyy),\n' +
'    map(p + e.yxy) - map(p - e.yxy),\n' +
'    map(p + e.yyx) - map(p - e.yyx)));\n' +
'}\n' +
'float softShadow(vec3 ro, vec3 rd){\n' +
'  float res = 1.0;\n' +
'  float t = 0.03;\n' +
'  for (int i = 0; i < 28; i++){\n' +
'    float h = map(ro + rd * t);\n' +
'    res = min(res, 9.0 * h / t);\n' +
'    t += clamp(h, 0.02, 0.4);\n' +
'    if (res < 0.005 || t > 10.0) break;\n' +
'  }\n' +
'  return clamp(res, 0.0, 1.0);\n' +
'}\n' +
'void main(){\n' +
'  vec2 uv = (gl_FragCoord.xy - 0.5*uRes) / uRes.y;\n' +
'  float t = uTime * uSpeed;\n' +
'  float steps = (uQuality < 0.5) ? 48.0 : ((uQuality < 1.5) ? 96.0 : 160.0);\n' +
'  vec3 ro = vec3(0.0, 1.15, 3.6);\n' +
'  vec3 ta = vec3(0.0, 0.85, 0.0);\n' +
'  vec3 fw = normalize(ta - ro);\n' +
'  vec3 rt = normalize(cross(fw, vec3(0.0, 1.0, 0.0)));\n' +
'  vec3 up = cross(rt, fw);\n' +
'  vec3 rd = normalize(uv.x * rt + uv.y * up + 1.7 * fw);\n' +
'  float d = 0.0;\n' +
'  bool hit = false;\n' +
'  for (int i = 0; i < 160; i++){\n' +
'    if (float(i) > steps) break;\n' +
'    float h = map(ro + rd * d);\n' +
'    if (h < 0.0008){ hit = true; break; }\n' +
'    d += h;\n' +
'    if (d > 24.0) break;\n' +
'  }\n' +
'  vec3 col;\n' +
'  vec3 pal = (uMode < 0.5) ? vec3(1.0, 0.5, 0.3)\n' +
'          : (uMode < 1.5) ? vec3(1.0, 0.78, 0.35)\n' +
'          : (uMode < 2.5) ? vec3(0.3, 0.85, 0.85)\n' +
'          : vec3(0.62, 0.45, 1.0);\n' +
'  if (hit){\n' +
'    vec3 p = ro + rd * d;\n' +
'    vec3 n = calcNormal(p);\n' +
'    vec3 lig = normalize(vec3(0.6 + 0.35*uMouse.x, 0.9, -0.4 + 0.35*uMouse.y));\n' +
'    float sha = softShadow(p + n * 0.02, lig);\n' +
'    float dif = clamp(dot(n, lig), 0.0, 1.0) * sha;\n' +
'    float amb = 0.5 + 0.5 * n.y;\n' +
'    float fre = pow(clamp(1.0 + dot(n, rd), 0.0, 1.0), 4.0);\n' +
'    float spec = pow(clamp(dot(reflect(rd, n), lig), 0.0, 1.0), 48.0) * sha;\n' +
'    vec3 alb = (p.y < 0.0) ? vec3(0.10, 0.16, 0.20) : pal;\n' +
'    col = alb * (0.7*dif + 0.22*amb) + vec3(1.0, 0.96, 0.9) * spec * 0.9 + vec3(0.55, 0.7, 0.95) * fre * 0.22;\n' +
'  } else {\n' +
'    col = mix(vec3(0.012, 0.03, 0.06), vec3(0.05, 0.10, 0.16), 0.5 + 0.5*uv.y);\n' +
'  }\n' +
'  float fog = 1.0 - exp(-d * d * 0.0016);\n' +
'  col = mix(col, vec3(0.03, 0.06, 0.10), fog);\n' +
'  col = col / (1.0 + 0.8 * col);\n' +
'  col = pow(col, vec3(0.4545));\n' +
'  col += (hash21(gl_FragCoord.xy + fract(t) * 100.0) - 0.5) * 0.03;\n' +
'  gl_FragColor = vec4(col, 1.0);\n' +
'}\n';

/* ---- 2D pattern tiles ---- */
var TILE1 = PRE + 'uniform vec2 uRes;\nuniform float uTime;\n' + COMMON +
'void main(){\n' +
'  vec2 uv = (2.0 * gl_FragCoord.xy - uRes) / uRes.y;\n' +
'  float t = uTime * 0.3;\n' +
'  vec2 p = uv * 1.8;\n' +
'  float v = 0.0; float a = 0.55;\n' +
'  for (int i = 0; i < 5; i++){ v += a * noise(p + t * vec2(0.25, 0.13)); p *= 2.05; a *= 0.52; }\n' +
'  float r = pow(clamp(1.0 - abs(2.0 * v - 0.9), 0.0, 1.0), 1.8);\n' +
'  vec3 c = mix(vec3(0.015, 0.05, 0.09), vec3(0.10, 0.55, 0.65), r);\n' +
'  c += vec3(1.0, 0.45, 0.25) * pow(max(r - 0.78, 0.0) * 4.5, 2.0);\n' +
'  c += (hash21(gl_FragCoord.xy + t) - 0.5) * 0.04;\n' +
'  gl_FragColor = vec4(c, 1.0);\n' +
'}\n';

var TILE2 = PRE + 'uniform vec2 uRes;\nuniform float uTime;\n' + COMMON +
'void main(){\n' +
'  vec2 uv = (2.0 * gl_FragCoord.xy - uRes) / uRes.y * 1.4;\n' +
'  float t = uTime * 0.5;\n' +
'  vec2 g = floor(uv); vec2 f = fract(uv);\n' +
'  float d = 10.0;\n' +
'  for (int y = -1; y <= 1; y++)\n' +
'  for (int x = -1; x <= 1; x++){\n' +
'    vec2 o = vec2(float(x), float(y));\n' +
'    vec2 rnd = vec2(hash21(g + o), hash21(g + o + 7.31));\n' +
'    vec2 r = o - f + (rnd - 0.5) * 0.9 + 0.15 * vec2(sin(t + rnd.x * 6.28), cos(t + rnd.y * 6.28));\n' +
'    d = min(d, length(r));\n' +
'  }\n' +
'  vec3 c = mix(vec3(0.02, 0.03, 0.08), vec3(0.08, 0.22, 0.35), smoothstep(0.0, 0.6, d));\n' +
'  c += vec3(0.2, 0.85, 0.9) * exp(-d * 3.0) * 0.6;\n' +
'  c += vec3(0.9, 0.35, 0.6) * pow(smoothstep(0.5, 0.0, d), 2.0) * 0.25;\n' +
'  c += (hash21(gl_FragCoord.xy + t) - 0.5) * 0.03;\n' +
'  gl_FragColor = vec4(c, 1.0);\n' +
'}\n';

var TILE3 = PRE + 'uniform vec2 uRes;\nuniform float uTime;\n' + COMMON +
'void main(){\n' +
'  vec2 uv = (2.0 * gl_FragCoord.xy - uRes) / uRes.y * 1.2;\n' +
'  float t = uTime;\n' +
'  float r = length(uv);\n' +
'  float w1 = sin((uv.x * 0.8 + uv.y * 0.6) * 26.0 + t * 0.7);\n' +
'  float w2 = sin((-uv.x * 0.6 + uv.y * 0.8) * 26.0 - t * 0.45 + 2.0 * sin(r * 2.0));\n' +
'  float m = 0.5 + 0.5 * w1 * w2;\n' +
'  vec3 c = mix(vec3(0.02, 0.02, 0.06), vec3(0.45, 0.15, 0.75), m);\n' +
'  c += vec3(0.95, 0.45, 0.2) * pow(m, 6.0) * 0.8;\n' +
'  c *= 1.0 - 0.35 * r;\n' +
'  c += (hash21(gl_FragCoord.xy + t) - 0.5) * 0.035;\n' +
'  gl_FragColor = vec4(c, 1.0);\n' +
'}\n';

var TILE4 = PRE + 'uniform vec2 uRes;\nuniform float uTime;\n' + COMMON +
'void main(){\n' +
'  vec2 uv = (2.0 * gl_FragCoord.xy - uRes) / uRes.y * 1.5;\n' +
'  float t = uTime * 0.8;\n' +
'  float v = sin(uv.x * 5.0 + t * 1.1) * 0.5;\n' +
'  v += sin(uv.y * 5.0 + t * 0.9 + v) * 0.4;\n' +
'  v += sin(length(uv) * 6.0 - t * 0.7) * 0.3;\n' +
'  float b = 0.5 + 0.5 * sin(v * 4.0);\n' +
'  vec3 c = mix(vec3(0.01, 0.05, 0.10), vec3(0.15, 0.6, 0.65), b);\n' +
'  c += vec3(0.9, 0.8, 0.4) * pow(b, 8.0) * 0.5;\n' +
'  c += (hash21(gl_FragCoord.xy + t) - 0.5) * 0.03;\n' +
'  gl_FragColor = vec4(c, 1.0);\n' +
'}\n';

/* ================= RENDERER BOILERPLATE ================= */
var VERT = 'attribute vec2 p; void main(){ gl_Position = vec4(p, 0.0, 1.0); }';
var UNIFORMS = ['uRes','uTime','uMouse','uSpeed','uMode','uQuality','uSeed'];
var scenes = [];

function createRenderer(canvas, frag){
  var gl = canvas.getContext('webgl', { antialias:false, alpha:false }) ||
           canvas.getContext('experimental-webgl', { antialias:false, alpha:false });
  if (!gl) return null;
  function mkShader(type, src){
    var s = gl.createShader(type);
    gl.shaderSource(s, src);
    gl.compileShader(s);
    if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(s));
    return s;
  }
  var prog = gl.createProgram();
  gl.attachShader(prog, mkShader(gl.VERTEX_SHADER, VERT));
  gl.attachShader(prog, mkShader(gl.FRAGMENT_SHADER, frag));
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(prog));
  gl.useProgram(prog);
  var buf = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1, 3,-1, -1,3]), gl.STATIC_DRAW);
  var loc = gl.getAttribLocation(prog, 'p');
  gl.enableVertexAttribArray(loc);
  gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
  var u = {};
  UNIFORMS.forEach(function(n){ u[n] = gl.getUniformLocation(prog, n); });
  return {
    gl: gl, u: u, canvas: canvas,
    draw: function(){
      gl.uniform2f(u.uRes, canvas.width, canvas.height);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    }
  };
}

function addScene(canvas, frag, cfg){
  if (!canvas) return null;
  var r;
  try { r = createRenderer(canvas, frag); } catch(e){ window.console && console.warn(e); r = null; }
  if (!r) {
    var frame = canvas.closest('.gl-frame');
    if (frame) frame.classList.add('no-gl');
    return null;
  }
  r.speed   = (cfg.speed != null) ? cfg.speed : 1;
  r.mode    = (cfg.mode != null) ? cfg.mode : 0;
  r.quality = (cfg.quality != null) ? cfg.quality : 2;
  r.seed    = (cfg.seed != null) ? cfg.seed : 0;
  r.tOff    = (cfg.tOff != null) ? cfg.tOff : 0;
  r.mx = 0; r.my = 0; r.mc = 0;
  r.mxT = 0; r.myT = 0; r.mcT = 0;
  scenes.push(r);
  return r;
}

function bindMouse(canvas, r){
  if (!canvas || !r) return;
  function move(e){
    var rect = canvas.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    r.mxT = ((e.clientX - rect.left) / rect.width) * 2 - 1;
    r.myT = 1 - ((e.clientY - rect.top) / rect.height) * 2;
  }
  canvas.addEventListener('pointermove', move);
  canvas.addEventListener('pointerdown', function(e){ move(e); r.mcT = 1; });
  window.addEventListener('pointerup', function(){ r.mcT = 0; });
  canvas.addEventListener('pointerleave', function(){ r.mcT = 0; });
}

function sizeCanvas(c){
  var dpr = Math.min(window.devicePixelRatio || 1, 2);
  var rect = c.getBoundingClientRect();
  var w = Math.max(2, Math.round(rect.width * dpr));
  var h = Math.max(2, Math.round(rect.height * dpr));
  if (c.width !== w || c.height !== h) { c.width = w; c.height = h; }
}

/* ================= SCENES ================= */
var hero = addScene(document.getElementById('heroCanvas'), HERO_FRAG, { speed:1, quality:2 });
bindMouse(document.getElementById('heroCanvas'), hero);

var pg = addScene(document.getElementById('pgCanvas'), PG_FRAG, { speed:1, mode:1, quality:1, seed:0 });
bindMouse(document.getElementById('pgCanvas'), pg);

addScene(document.getElementById('tile1'), TILE1, { tOff:0 });
addScene(document.getElementById('tile2'), TILE2, { tOff:7.3 });
addScene(document.getElementById('tile3'), TILE3, { tOff:13.9 });
addScene(document.getElementById('tile4'), TILE4, { tOff:3.1 });

/* ================= PLAYGROUND CONTROLS ================= */
var stepNames = [48, 96, 160];
var modeSeg = document.getElementById('modeSeg');
var qualSeg = document.getElementById('qualSeg');
var speedInput = document.getElementById('speed');
var speedVal = document.getElementById('speedVal');
var stepVal = document.getElementById('stepVal');
var stepFoot = document.getElementById('stepFoot');
var seedBtn = document.getElementById('seedBtn');

modeSeg.addEventListener('click', function(e){
  var b = e.target.closest('button[data-mode]');
  if (!b || !pg) return;
  pg.mode = parseInt(b.dataset.mode, 10);
  modeSeg.querySelectorAll('button').forEach(function(x){ x.classList.toggle('on', x === b); });
});
qualSeg.addEventListener('click', function(e){
  var b = e.target.closest('button[data-q]');
  if (!b || !pg) return;
  var q = parseInt(b.dataset.q, 10);
  pg.quality = q;
  qualSeg.querySelectorAll('button').forEach(function(x){ x.classList.toggle('on', x === b); });
  stepVal.textContent = stepNames[q] + ' steps';
  stepFoot.textContent = stepNames[q];
});
speedInput.addEventListener('input', function(){
  var v = parseFloat(speedInput.value);
  if (pg) pg.speed = v;
  speedVal.textContent = v.toFixed(2) + '×';
});
seedBtn.addEventListener('click', function(){
  if (!pg) return;
  pg.seed = Math.random() * 100;
  seedBtn.textContent = '✓  Re-seeded';
  setTimeout(function(){ seedBtn.innerHTML = '⟲&nbsp; New seed'; }, 1200);
});

/* ================= MAIN LOOP ================= */
var t0 = performance.now();
var frames = 0;
var lastFps = t0;
var fpsEl = document.getElementById('fps');

function frame(){
  var t = (performance.now() - t0) / 1000;
  for (var i = 0; i < scenes.length; i++){
    var r = scenes[i];
    sizeCanvas(r.canvas);
    if (r.canvas.clientWidth <= 0) continue;
    r.mx += (r.mxT - r.mx) * 0.05;
    r.my += (r.myT - r.my) * 0.05;
    r.mc += (r.mcT - r.mc) * 0.08;
    r.gl.uniform1f(r.u.uTime, t + r.tOff);
    r.gl.uniform3f(r.u.uMouse, r.mx, r.my, r.mc);
    r.gl.uniform1f(r.u.uSpeed, r.speed);
    r.gl.uniform1f(r.u.uQuality, r.quality);
    r.gl.uniform1f(r.u.uSeed, r.seed);
    if (r.u.uMode) r.gl.uniform1f(r.u.uMode, r.mode);
    r.draw();
    frames++;
  }
  var now = performance.now();
  if (now - lastFps > 500 && fpsEl){
    fpsEl.textContent = Math.max(1, Math.round(frames * 1000 / (now - lastFps)));
    frames = 0;
    lastFps = now;
  }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

})();
</script>
</body>
</html>
"}

